using System;
using System.Data;
using System.Text.RegularExpressions;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;

namespace InformationCMS.Controls.ContenPageAuto
{
    public partial class List : ControlBase
    {
        private const int PageSize = 25;
        private const string EditPage = "~/Pages/1ContenPageAuto/Edit.aspx";

        protected String strPermissionView = "INFO_AboutPageContent_View";
        protected String strPermissionAddEdit = "INFO_AboutPageContent_AddEdit";
        protected String strPermissionDelete = "INFO_AboutPageContent_Delete";

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                SetPermission();

                if (Session["ContentPageAuto_List_PageIndex"] != null)
                {
                    RestoreListState();
                }
                else
                {
                    GridDatabind(0);
                }
            }
        }

        private void SetPermission()
        {
            if (!User.IsPermission(strPermissionView)
                && !User.IsPermission(strPermissionAddEdit)
                && !User.IsPermission(strPermissionDelete))
            {
                Session[DCore.Globals.ERROR] = new SystemError("Bạn không được phép truy cập chức năng này", null, ReturnPage);
                Response.Redirect("~/" + MessagePage);
            }

            btnAddNew.Visible = User.IsPermission(strPermissionAddEdit);
        }

        private void GridDatabind(int intPageIndex)
        {
            int? intIsPublished = null;
            if (!string.IsNullOrWhiteSpace(ddlIsPublished.SelectedValue))
                intIsPublished = Convert.ToInt32(ddlIsPublished.SelectedValue);

            DataTable dtbData = AboutPageContentService.Search(
                ddlPageCode.SelectedValue,
                ddlSectionCode.SelectedValue,
                txtSearch.Text.Trim(),
                intIsPublished
            );

            grvObject.PageSize = PageSize;
            grvObject.PageIndex = intPageIndex;
            grvObject.DataSource = dtbData;
            grvObject.DataBind();
            udpList.Update();
        }

        private void SaveListState()
        {
            Session["ContentPageAuto_List_PageCode"] = ddlPageCode.SelectedValue;
            Session["ContentPageAuto_List_SectionCode"] = ddlSectionCode.SelectedValue;
            Session["ContentPageAuto_List_SearchText"] = txtSearch.Text;
            Session["ContentPageAuto_List_IsPublished"] = ddlIsPublished.SelectedValue;
            Session["ContentPageAuto_List_PageIndex"] = grvObject.PageIndex;
        }

        private void RestoreListState()
        {
            if (Session["ContentPageAuto_List_PageCode"] != null)
                ddlPageCode.SelectedValue = Session["ContentPageAuto_List_PageCode"].ToString();

            if (Session["ContentPageAuto_List_SectionCode"] != null)
                ddlSectionCode.SelectedValue = Session["ContentPageAuto_List_SectionCode"].ToString();

            if (Session["ContentPageAuto_List_SearchText"] != null)
                txtSearch.Text = Session["ContentPageAuto_List_SearchText"].ToString();

            if (Session["ContentPageAuto_List_IsPublished"] != null)
                ddlIsPublished.SelectedValue = Session["ContentPageAuto_List_IsPublished"].ToString();

            int intPageIndex = 0;
            if (Session["ContentPageAuto_List_PageIndex"] != null)
                intPageIndex = Convert.ToInt32(Session["ContentPageAuto_List_PageIndex"]);

            Session.Remove("ContentPageAuto_List_PageCode");
            Session.Remove("ContentPageAuto_List_SectionCode");
            Session.Remove("ContentPageAuto_List_SearchText");
            Session.Remove("ContentPageAuto_List_IsPublished");
            Session.Remove("ContentPageAuto_List_PageIndex");

            GridDatabind(intPageIndex);
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            GridDatabind(0);
        }

        protected void grvObject_RowCreated(object sender, GridViewRowEventArgs e)
        {
            if (e.Row.RowType == DataControlRowType.Header)
                e.Row.CssClass = "cus-thead";
        }

        protected void grvObject_PageIndexChanging(object sender, GridViewPageEventArgs e)
        {
            GridDatabind(e.NewPageIndex);
        }

        protected void lbtEdit_Click(object sender, EventArgs e)
        {
            SaveListState();
            Response.Redirect(ResolveUrl(EditPage) + "?id=" + ((LinkButton)sender).CommandArgument);
        }

        protected void btnAddNew_Click(object sender, EventArgs e)
        {
            SaveListState();
            Response.Redirect(ResolveUrl(EditPage));
        }

        protected void lbtDelete_Click(object sender, EventArgs e)
        {
            if (!User.IsPermission(strPermissionDelete))
            {
                MsgBox.ShowError("Bạn không có quyền xóa");
                return;
            }

            LinkButton lbtTemp = sender as LinkButton;
            if (lbtTemp == null) return;

            AboutPageContentService.Delete(Convert.ToInt64(lbtTemp.CommandArgument), User.UserName);
            MsgBox.ShowSuccess("Đã xóa nội dung");
            GridDatabind(grvObject.PageIndex);
        }

        protected string GetContentPreview(object objValue)
        {
            if (objValue == null || objValue == DBNull.Value)
                return string.Empty;

            string strText = Convert.ToString(objValue);
            if (string.IsNullOrEmpty(strText))
                return string.Empty;

            strText = Regex.Replace(strText, "<[^>]+>", " ");
            strText = strText.Replace("\r", " ").Replace("\n", " ").Trim();

            while (strText.Contains("  "))
                strText = strText.Replace("  ", " ");

            return strText;
        }
    }
}
